      "summary": "首页 > 科研进展 CCHFV是高致病性蜱传RNA病毒，目前尚无特异性的抗病毒药物和疫苗获批临床使用。 近日，中国科学院武汉病毒研究所报道了产物链长度为14个核苷酸的CCHFV RdRP延伸复合物（EC14，分辨率3.0埃）的冷冻电镜结构。 该结构较完整地呈现了CCHFV L蛋白的整体构架，并鉴定出多个可能与复制相关的",
